CalculatorElement.MainFunction:
{
in(0,3)
curv{ApplyGamma}
mtx{RgbToWpt}
ctop 360 div
tput{wch}
tget{wch.c}
0.00000001 lt if
{
  tget{wch.w}
  copy(1,30)
}
else
{
  tget{wch.h}
  tint{HueToReflectanceWC}
  tget{wch.c}
  flip
  div
  tsav{s_chromatic}
  mul
  neg
  tget{wch.w}
  add
  tput{s_achromatic}
  tget{s_chromatic}
  smul(31)
  tget{s_achromatic}
  sadd(31)
}
out(0,31)
}
